            "answer": 2,
            "explanation": "Trưởng nhóm Minh Đức nêu rõ tàu không chở khách hay xét nghiệm hóa chất, mà nhằm tự động hóa việc vớt rác nhựa nổi trên mặt kênh bằng năng lượng mặt trời.",
            "tapescript": "PART 2 – (Questions 6–10) A radio report about a solar-powered river-cleaning boat called ClearStream\nPresenter: Welcome to ‘Young Innovators’. Today we visit Đà Nẵng, where a team of young engineers and secondary-school mentors has built ClearStream, a compact solar-powered catamaran that collects floating plastic waste along urban canals.\nProject leader Mr Minh Đức explains what the boat was designed to do.\nMr Minh Đức: “When passers-by see ClearStream gliding along the canal, they often think it’s a water-quality laboratory testing chemical pollution, or a ferry for tourists. In fact, it carries no passengers. Sanitation workers spend hours in small rowboats scooping up plastic bottles by hand under the blazing sun, and our main goal was to automate that exhausting surface skimming using clean solar energy.”\nPresenter: ClearStream follows a pre-mapped GPS route along the canal. In dry weather, it cruises down the centre of the waterway. However, onboard cameras scan the water surface, and whenever heavy rain washes a dense patch of floating rubbish against the canal bank, the boat steers closer to the wall and deploys a flexible side-arm to sweep the bottles onto its conveyor belt.\nBecause canal bridges are often low, ClearStream cannot use tall masts. Instead, its flat roof is covered with lightweight solar panels connected to a lithium battery bank. That battery bank does two jobs throughout the day: it powers the quiet electric twin-motors even under shady bridges, and it runs an onboard compactor that crushes plastic bottles to double the bin’s capacity.\nInterestingly, the conveyor belt’s mesh came from a local fishing-gear workshop in Thanh Hóa. The workshop knew nothing about solar panels or GPS navigation, but for decades it has woven snag-resistant nylon nets that let small fish swim through while catching larger debris—which turned out to be ideal for scooping up bottles without harming surface minnows.\nWill we soon see ClearStream operating in every city canal across Vietnam? Mr Đức remains realistic.\nMr Minh Đức: “Environmental departments love the prototype, but each canal has different bridge heights and weed growth. Until we complete our six-month monsoon durability test this autumn, we won’t start mass production.”",
