            "instruction": "I. LISTENING - Part 2: You will hear a radio report about anautonomous pollination drone system called RoboBee. Forquestions 6-10, choose the answer (A, B, C or D) which fitsbest according to what you hear.",
            "text": "AgriTech Delft developed the RoboBee micro-drones mainly tohelp commercial glasshouse growers __________.",
