            "tapescript": "PART 1 – (Questions 1–5) A youth club coordinator speaking to Grade 9 student volunteers about a community book-swap and recycling day\nMs Lan: Good morning, everyone! Thank you for coming to the school library early. I’d like to go over the final plan for our Grade 9 Community Book-Swap and Eco-Fair.\nFirst, the date. On the poster in the hallway, we originally wrote Saturday the tenth of May. However, the district sports tournament is using the school courtyard that morning, so we’ve moved our fair to Sunday the eleventh. A few students asked if Saturday the seventeenth would work, but that’s right before your final term exams, so Sunday the eleventh is our confirmed date.\nNow, about our fundraising goal for the mountainous school library in Mường Lát. Last year we hoped to raise ten million dong and finished two million short. Our second-hand comic stall brought in four million, which was great. Some of you suggested charging a twenty-thousand-dong entrance ticket at the school gate, but our headmaster wants the fair to remain completely free for all neighbourhood children. That means our handmade craft and eco-workshop stalls inside the courtyard must bring in the extra two million dong this year.\nTwo of you will be looking after the Recycled Paper-Making table. Visitors blend old newspapers with water and press the pulp onto a mesh frame. People think beginners struggle because the wooden frame is heavy, or because the blender is noisy. Actually, the frames are light bamboo. The real trick is that you must sponge off the excess water firmly before lifting the mesh; if you lift it too soon while it’s dripping wet, the paper sheet tears right down the middle.\nNext to the library steps is our Canvas Tote-Bag Painting stall, which is always a huge favourite with Grade 9 students. At thirty thousand dong a bag, it’s the same price as a glass of peach tea, and there’s always a queue. Why do students love it so much? Because even if someone isn’t confident at drawing, our art club members help them stencil their own name and a green leaf logo onto the bag, so everyone walks away with a unique schoolbag they’re proud to carry.\nLast year, that stall made a clear profit of one million two hundred thousand dong after we subtracted three hundred thousand dong for the plain canvas bags and fabric paint. Let’s get the tables ready!",
