            "tapescript": "PART 3 – (Questions 11–15) An interview with Mai Anh, a young artisan reviving traditional sedge-mat weaving in Nga Sơn, Thanh Hóa\nInterviewer: Mai Anh, welcome. Most university graduates in business head for big cities, yet you returned to your home village in Nga Sơn, Thanh Hóa, to run a traditional sedge-mat cooperative. How did that come about?\nMai Anh: People were certainly surprised! I completed a degree in international e-commerce in Hanoi, and then spent a year learning natural plant-dyeing techniques from my grandmother at home. My classmates thought I was wasting my university degree. But I realised that traditional Nga Sơn sedge mats were struggling not because the craftsmanship was poor, but because village weavers didn’t know how to design foldable, contemporary homeware for online export markets. Combining e-commerce with traditional weaving bridged that gap.\nInterviewer: Your cooperative now supplies eco-friendly mats and baskets to boutique hotels and foreign buyers. Are international hotel clients difficult to work with?\nMai Anh: They have very strict standards! One Japanese hotelier asked us to weave three hundred tatami-style sedge cushions with zero variation in colour or thickness—which meant we had to sort every single sedge stalk by hand. It was exhausting. Even so, hotel contracts pay three times the price of local market stalls, and that steady income allows us to pay seventy village women a fair monthly wage right in their hometown, so I’m delighted to meet their standards.\nInterviewer: What’s the most rewarding moment of your workday?\nMai Anh: Outsiders assume it’s seeing our products featured in lifestyle magazines or winning startup awards in Hanoi. Those are lovely, of course. But my favourite moment is early in the morning at the drying yard, when the sun hits the freshly dyed red and golden sedge stalks and I hear the rhythmic click-clack of wooden looms echoing from the houses along the lane—a sound that had almost vanished when I was in high school.\nInterviewer: You’ve also faced tough challenges. Last September, unseasonal heavy rain hit right during the peak sedge harvest.\nMai Anh: Yes, it rained for six days solid. Sedge stalks turn mouldy within forty-eight hours if they can’t be sun-dried. We rented three industrial agricultural dryers from a neighbouring commune and saved ninety percent of the harvest. The district Youth Union praised our quick thinking, and everyone expected me to feel relieved. Honestly, I felt frustrated with myself for having relied entirely on open-air sun-drying in an era of unpredictable weather.\nInterviewer: What has your cooperative changed since last September?\nMai Anh: We haven’t raised the prices of our mats, and we still dry sedge in the sun whenever the sky is clear. However, we’ve pooled our profits to build two solar-assistedgreenhouse drying sheds with dehumidifiers right inside the village, so a sudden autumn storm can never threaten our weavers’ livelihoods again.",
